export function byDepartment() {
  const active = EMPLOYEES.filter(isActive);
  return [...new Set(active.map((e) => e.department))]
    .map((d) => ({ department: d, count: active.filter((e) => e.department === d).length }))
    .sort((a, b) => b.count - a.count);
}
